/* =========================================================
   Duel of Shadows — UI shell
   ========================================================= */
@font-face {
  font-family: "Vazirmatn";
  src: url("assets/fonts/Vazirmatn-Regular.woff2") format("woff2");
  font-weight: 400;
  font-display: swap;
}
@font-face {
  font-family: "Vazirmatn";
  src: url("assets/fonts/Vazirmatn-Bold.woff2") format("woff2");
  font-weight: 700;
  font-display: swap;
}
@font-face {
  font-family: "Vazirmatn";
  src: url("assets/fonts/Vazirmatn-Black.woff2") format("woff2");
  font-weight: 900;
  font-display: swap;
}

:root {
  --ink: #0a0612;
  --paper: #f7efe6;
  --muted: #a79bb8;
  --ember: #ff6a3d;
  --ember-soft: #ffb26b;
  --ice: #5be7ff;
  --ice-soft: #a8f3ff;
  --gold: #ffd27a;
  --panel: rgba(17, 10, 27, 0.92);
  --line: rgba(255, 255, 255, 0.12);
  --font: "Vazirmatn", "Segoe UI", Tahoma, sans-serif;
}

* { box-sizing: border-box; }

html, body {
  height: 100%;
  margin: 0;
}

body {
  background:
    radial-gradient(120% 90% at 50% 0%, #231331 0%, #0b0712 58%, #05030a 100%);
  color: var(--paper);
  font-family: var(--font);
  overflow: hidden;
  display: grid;
  place-items: center;
  height: 100dvh;
  -webkit-tap-highlight-color: transparent;
  user-select: none;
  -webkit-user-select: none;
  overscroll-behavior: none;
}

#frame {
  position: relative;
  width: min(100vw, calc(100dvh * 16 / 9));
  height: min(100dvh, calc(100vw * 9 / 16));
  overflow: hidden;
  box-shadow: 0 0 120px rgba(255, 106, 61, 0.08), 0 30px 80px rgba(0, 0, 0, 0.8);
  background: #0a0612;
}

canvas#game {
  display: block;
  width: 100%;
  height: 100%;
  touch-action: none;
}

#ui {
  position: absolute;
  inset: 0;
  pointer-events: none;
  font-family: var(--font);
}

#ui button { font-family: inherit; }

/* =========================================================
   Screens
   ========================================================= */
.screen {
  position: absolute;
  inset: 0;
  pointer-events: auto;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: clamp(10px, 2.2vmin, 30px);
  overflow: auto;
}

.screen[hidden] { display: none !important; }

.menu-screen {
  background:
    radial-gradient(64% 70% at 50% 44%, rgba(10, 6, 18, 0.2) 0%, rgba(8, 5, 14, 0.66) 66%, rgba(5, 3, 10, 0.92) 100%);
  animation: screen-in 0.45s ease both;
}

.dim-screen {
  background: rgba(6, 4, 12, 0.62);
  backdrop-filter: blur(3px);
  animation: screen-in 0.28s ease both;
}

@keyframes screen-in {
  from { opacity: 0; }
  to { opacity: 1; }
}

/* =========================================================
   Menu panel
   ========================================================= */
.menu-panel {
  position: relative;
  width: min(100%, 1040px);
  padding: clamp(16px, 3.1vmin, 34px) clamp(18px, 4vmin, 54px) clamp(14px, 2.4vmin, 26px);
  border: 1px solid rgba(255, 210, 160, 0.14);
  border-radius: 22px;
  background:
    linear-gradient(150deg, rgba(32, 18, 44, 0.94), rgba(12, 7, 21, 0.96) 62%),
    radial-gradient(120% 80% at 0% 0%, rgba(255, 106, 61, 0.14), transparent 60%);
  box-shadow:
    0 30px 90px rgba(0, 0, 0, 0.6),
    inset 0 1px 0 rgba(255, 255, 255, 0.06);
  overflow: hidden;
}
.menu-panel::before,
.menu-panel::after {
  content: "";
  position: absolute;
  width: 160px;
  height: 2px;
  background: linear-gradient(90deg, transparent, rgba(255, 178, 107, 0.55));
  top: 0;
}
.menu-panel::before { left: 0; }
.menu-panel::after { right: 0; transform: scaleX(-1); }

.menu-head { text-align: center; position: relative; }

.eyebrow {
  margin: 0 0 6px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  color: var(--ember-soft);
  font-size: clamp(9px, 1.45vmin, 12px);
  letter-spacing: 0.18em;
  font-weight: 700;
}
.eyebrow span {
  display: block;
  width: clamp(24px, 5vmin, 54px);
  height: 1px;
  background: linear-gradient(90deg, transparent, rgba(255, 178, 107, 0.65));
}
.eyebrow span:last-child { transform: scaleX(-1); }

.menu-head h1 {
  margin: 0;
  font-size: clamp(40px, 7.4vmin, 82px);
  font-weight: 900;
  line-height: 1.02;
  letter-spacing: -0.01em;
  color: #fff7ee;
  text-shadow:
    0 2px 0 rgba(255, 255, 255, 0.08),
    0 18px 46px rgba(255, 106, 61, 0.22);
}
.menu-head h1 em {
  font-style: normal;
  background: linear-gradient(178deg, #ffe3b0 2%, var(--ember) 48%, #ff2f6d 100%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  filter: drop-shadow(0 4px 18px rgba(255, 106, 61, 0.35));
}

.latin-title {
  margin: 4px 0 0;
  font-size: clamp(8px, 1.25vmin, 11px);
  letter-spacing: 0.62em;
  color: rgba(255, 235, 214, 0.45);
  direction: ltr;
  padding-left: 0.62em;
}
.tagline {
  margin: 10px 0 0;
  font-size: clamp(11px, 1.7vmin, 15px);
  color: var(--muted);
}

/* ---------------- Versus ---------------- */
.versus {
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: stretch;
  gap: clamp(8px, 1.8vmin, 20px);
  margin: clamp(12px, 2.4vmin, 24px) 0 clamp(12px, 2.2vmin, 22px);
}

.fighter-card {
  position: relative;
  display: flex;
  align-items: center;
  gap: clamp(10px, 1.8vmin, 18px);
  padding: clamp(10px, 1.6vmin, 15px) clamp(12px, 2vmin, 20px);
  border-radius: 14px;
  border: 1px solid rgba(255, 106, 61, 0.24);
  background:
    linear-gradient(140deg, rgba(255, 106, 61, 0.14), rgba(255, 106, 61, 0.02) 55%),
    rgba(255, 255, 255, 0.025);
  text-align: right;
  overflow: hidden;
}
.fighter-card.p2 {
  border-color: rgba(91, 231, 255, 0.24);
  background:
    linear-gradient(140deg, rgba(91, 231, 255, 0.13), rgba(91, 231, 255, 0.02) 55%),
    rgba(255, 255, 255, 0.025);
  text-align: left;
}
.fighter-card::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(100deg, transparent 40%, rgba(255, 255, 255, 0.06) 50%, transparent 60%);
  transform: translateX(-120%);
  animation: sheen 7s ease-in-out infinite;
}
@keyframes sheen {
  0%, 62% { transform: translateX(-120%); }
  82%, 100% { transform: translateX(120%); }
}

.crest {
  flex: 0 0 auto;
  width: clamp(46px, 8vmin, 74px);
  aspect-ratio: 1;
  border-radius: 50%;
  display: grid;
  place-items: center;
  font-size: clamp(22px, 4vmin, 36px);
  font-weight: 900;
  color: #1a0b0f;
  background:
    radial-gradient(circle at 34% 28%, #ffd9a8, var(--ember) 46%, #7c1f35 100%);
  box-shadow:
    0 0 0 1px rgba(255, 213, 170, 0.5),
    0 0 30px rgba(255, 106, 61, 0.35),
    inset 0 -8px 18px rgba(60, 8, 24, 0.55);
}
.p2 .crest {
  color: #04222a;
  background:
    radial-gradient(circle at 34% 28%, #e6fdff, var(--ice) 46%, #1f4f7c 100%);
  box-shadow:
    0 0 0 1px rgba(200, 250, 255, 0.5),
    0 0 30px rgba(91, 231, 255, 0.3),
    inset 0 -8px 18px rgba(8, 34, 60, 0.5);
}

.fighter-meta { min-width: 0; }
.fighter-meta h2 {
  margin: 0;
  font-size: clamp(18px, 3vmin, 27px);
  font-weight: 900;
  color: #fff4e8;
  line-height: 1.1;
}
.fighter-meta .latin {
  margin: 3px 0 5px;
  direction: ltr;
  text-align: inherit;
  color: var(--ember-soft);
  font-size: clamp(7px, 1.1vmin, 10px);
  letter-spacing: 0.24em;
  font-weight: 700;
}
.p2 .fighter-meta .latin { color: var(--ice-soft); }
.fighter-meta .desc {
  margin: 0;
  color: var(--muted);
  font-size: clamp(9px, 1.4vmin, 12px);
  line-height: 1.6;
}
.badge {
  position: absolute;
  top: 8px;
  inset-inline-end: 10px;
  font-size: clamp(7px, 1.1vmin, 9.5px);
  letter-spacing: 0.06em;
  color: rgba(255, 235, 214, 0.55);
  background: rgba(0, 0, 0, 0.28);
  border: 1px solid rgba(255, 255, 255, 0.1);
  padding: 2px 7px;
  border-radius: 999px;
}
.p2 .badge { inset-inline-end: auto; inset-inline-start: 10px; }

.vs-mark {
  align-self: center;
  display: grid;
  place-items: center;
  width: clamp(38px, 6vmin, 60px);
  aspect-ratio: 1;
  border-radius: 50%;
  border: 1px solid rgba(255, 255, 255, 0.12);
  background: radial-gradient(circle, rgba(30, 18, 40, 0.9), rgba(10, 6, 18, 0.85));
  box-shadow: 0 0 24px rgba(0, 0, 0, 0.6);
  transform: rotate(-6deg);
}
.vs-mark span {
  font-size: clamp(12px, 2vmin, 19px);
  font-weight: 900;
  font-style: italic;
  color: #ffe9cf;
  letter-spacing: -0.02em;
}

/* ---------------- Actions ---------------- */
.menu-actions {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: clamp(8px, 1.4vmin, 12px);
}

.mode-row {
  display: inline-flex;
  padding: 4px;
  gap: 4px;
  border-radius: 12px;
  border: 1px solid var(--line);
  background: rgba(0, 0, 0, 0.28);
}
.mode {
  appearance: none;
  border: 0;
  cursor: pointer;
  padding: clamp(5px, 0.9vmin, 8px) clamp(12px, 2vmin, 22px);
  border-radius: 8px;
  background: transparent;
  color: var(--muted);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 1px;
  transition: background 0.2s, color 0.2s, box-shadow 0.2s;
}
.mode strong { font-size: clamp(10px, 1.55vmin, 13px); font-weight: 700; }
.mode span { font-size: clamp(7.5px, 1.15vmin, 9.5px); opacity: 0.65; }
.mode:hover { color: #fff; }
.mode.active {
  color: #1b0a10;
  background: linear-gradient(170deg, #ffd9a8, var(--ember-soft));
  box-shadow: 0 4px 16px rgba(255, 106, 61, 0.25);
}

.cta {
  position: relative;
  appearance: none;
  cursor: pointer;
  border: 0;
  width: min(100%, 380px);
  padding: clamp(9px, 1.6vmin, 14px) 26px;
  border-radius: 12px;
  background: linear-gradient(170deg, #ffe3b4 0%, #ffab5c 34%, var(--ember) 78%, #ff3d63 100%);
  color: #22100d;
  box-shadow:
    0 10px 30px rgba(255, 90, 54, 0.26),
    inset 0 1px 0 rgba(255, 255, 255, 0.6),
    inset 0 -3px 0 rgba(110, 20, 30, 0.25);
  transition: transform 0.12s ease, box-shadow 0.2s ease, filter 0.2s;
  overflow: hidden;
}
.cta::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(100deg, transparent 35%, rgba(255, 255, 255, 0.5) 50%, transparent 65%);
  transform: translateX(-130%) skewX(-12deg);
  transition: transform 0.6s ease;
}
.cta:hover { filter: brightness(1.05); box-shadow: 0 14px 38px rgba(255, 90, 54, 0.36), inset 0 1px 0 rgba(255, 255, 255, 0.6); }
.cta:hover::after { transform: translateX(130%) skewX(-12deg); }
.cta:active { transform: translateY(2px) scale(0.995); }
.cta-main {
  display: block;
  font-size: clamp(15px, 2.3vmin, 20px);
  font-weight: 900;
  letter-spacing: 0.01em;
}
.cta-sub {
  display: block;
  direction: ltr;
  font-size: clamp(7px, 1.1vmin, 9px);
  letter-spacing: 0.32em;
  opacity: 0.55;
  font-weight: 700;
  margin-top: 1px;
}
.cta.small { width: auto; min-width: 190px; }

.sub-row {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
  justify-content: center;
}
.ghost-btn {
  appearance: none;
  cursor: pointer;
  border: 1px solid var(--line);
  background: rgba(255, 255, 255, 0.04);
  color: #d9cfe4;
  border-radius: 9px;
  padding: clamp(5px, 0.9vmin, 8px) clamp(12px, 1.8vmin, 17px);
  font-size: clamp(9px, 1.4vmin, 12px);
  transition: background 0.2s, border-color 0.2s, color 0.2s;
}
.ghost-btn:hover { background: rgba(255, 255, 255, 0.08); border-color: rgba(255, 200, 150, 0.3); color: #fff; }
#btn-sound .sound-off { display: none; }
#btn-sound[aria-pressed="true"] .sound-on { display: none; }
#btn-sound[aria-pressed="true"] .sound-off { display: inline; }

.menu-foot {
  margin-top: clamp(8px, 1.5vmin, 14px);
  padding-top: clamp(8px, 1.3vmin, 12px);
  border-top: 1px solid rgba(255, 255, 255, 0.06);
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 12px;
  color: rgba(200, 185, 215, 0.55);
  font-size: clamp(8px, 1.2vmin, 10px);
}
.menu-foot .sep { width: 3px; height: 3px; border-radius: 50%; background: rgba(255, 255, 255, 0.3); }

/* ---------------- Controls panel ---------------- */
.controls-panel {
  margin-top: clamp(10px, 1.8vmin, 16px);
  padding-top: clamp(10px, 1.6vmin, 14px);
  border-top: 1px solid rgba(255, 255, 255, 0.08);
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: clamp(10px, 2vmin, 26px);
  animation: panel-in 0.25s ease both;
}
.controls-panel[hidden] { display: none; }
@keyframes panel-in {
  from { opacity: 0; transform: translateY(-4px); }
  to { opacity: 1; transform: none; }
}
.controls-col h3 {
  margin: 0 0 7px;
  font-size: clamp(10px, 1.55vmin, 13px);
  display: flex;
  align-items: center;
  gap: 7px;
  color: #f4e9f7;
}
.dot { width: 7px; height: 7px; border-radius: 50%; display: inline-block; }
.dot.p1 { background: var(--ember); box-shadow: 0 0 8px var(--ember); }
.dot.p2 { background: var(--ice); box-shadow: 0 0 8px var(--ice); }
.controls-col ul {
  margin: 0;
  padding: 0;
  list-style: none;
  display: grid;
  gap: 4px;
}
.controls-col li {
  display: flex;
  align-items: center;
  gap: 5px;
  font-size: clamp(8.5px, 1.25vmin, 11px);
  color: #b7abc6;
}
.controls-col li span { flex: 1 1 auto; }
.controls-col li small { opacity: 0.6; font-size: 0.85em; }
kbd {
  font-family: var(--font);
  font-weight: 700;
  font-size: 0.92em;
  min-width: 20px;
  text-align: center;
  padding: 1px 5px;
  border-radius: 5px;
  border: 1px solid rgba(255, 255, 255, 0.16);
  border-bottom-width: 2px;
  background: rgba(255, 255, 255, 0.06);
  color: #efe5f5;
  direction: ltr;
}
.controls-tip {
  grid-column: 1 / -1;
  display: flex;
  flex-wrap: wrap;
  gap: 6px 22px;
  padding-top: 8px;
  border-top: 1px dashed rgba(255, 255, 255, 0.07);
}
.controls-tip p { margin: 0; font-size: clamp(8px, 1.15vmin, 10px); color: #9b8dab; }
.controls-tip strong { color: #d8cbe4; }

/* ---------------- Dialogs ---------------- */
.dialog {
  width: min(92%, 520px);
  padding: clamp(20px, 4vmin, 40px);
  border-radius: 18px;
  border: 1px solid rgba(255, 210, 160, 0.16);
  background:
    linear-gradient(160deg, rgba(30, 17, 42, 0.97), rgba(11, 7, 19, 0.98));
  box-shadow: 0 30px 80px rgba(0, 0, 0, 0.65), inset 0 1px 0 rgba(255, 255, 255, 0.06);
  text-align: center;
  animation: dialog-in 0.32s cubic-bezier(0.2, 0.9, 0.3, 1.2) both;
}
@keyframes dialog-in {
  from { opacity: 0; transform: translateY(10px) scale(0.97); }
  to { opacity: 1; transform: none; }
}
.dialog h2 {
  margin: 8px 0 4px;
  font-size: clamp(24px, 4.6vmin, 44px);
  font-weight: 900;
  color: #fff4e8;
}
.dialog-sub {
  margin: 0 0 clamp(14px, 2.6vmin, 22px);
  color: var(--muted);
  font-size: clamp(11px, 1.8vmin, 15px);
}
.dialog-actions {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
}
.dialog-actions .ghost-btn { min-width: 160px; }
.result .eyebrow { margin-bottom: 0; }
.result-score {
  display: flex;
  justify-content: center;
  gap: 12px;
  margin: 0 0 18px;
}
.score-pip {
  width: 14px;
  height: 14px;
  border-radius: 3px;
  transform: rotate(45deg);
  border: 1px solid rgba(255, 255, 255, 0.2);
  background: rgba(255, 255, 255, 0.06);
}
.score-pip.win.p1 { background: linear-gradient(140deg, #ffd9a8, var(--ember)); border-color: transparent; box-shadow: 0 0 12px rgba(255, 106, 61, 0.5); }
.score-pip.win.p2 { background: linear-gradient(140deg, #e0fdff, var(--ice)); border-color: transparent; box-shadow: 0 0 12px rgba(91, 231, 255, 0.45); }
.score-pip.win.draw { background: rgba(255, 255, 255, 0.35); }

/* =========================================================
   Touch controls
   ========================================================= */
.touch-controls {
  position: absolute;
  inset: auto 0 0 0;
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  padding: 0 clamp(10px, 2.4vmin, 26px) calc(clamp(10px, 2vmin, 20px) + env(safe-area-inset-bottom));
  pointer-events: none;
  --ts: clamp(38px, 7.2vmin, 58px);
}
.touch-controls[hidden] { display: none !important; }

.touch-side {
  display: flex;
  align-items: flex-end;
  gap: clamp(8px, 1.8vmin, 18px);
  pointer-events: none;
  transition: opacity 0.2s;
}
.touch-side.p1 { flex-direction: row-reverse; }
.touch-side .dpad,
.touch-side .atk-grid { pointer-events: auto; }

.dpad {
  display: grid;
  grid-template-columns: repeat(3, calc(var(--ts) * 0.82));
  grid-template-rows: repeat(3, calc(var(--ts) * 0.82));
  gap: 3px;
  touch-action: none;
}
.dbtn {
  appearance: none;
  border: 1px solid rgba(255, 255, 255, 0.18);
  background: rgba(14, 9, 24, 0.55);
  color: rgba(255, 245, 235, 0.92);
  border-radius: 11px;
  font-size: calc(var(--ts) * 0.3);
  backdrop-filter: blur(2px);
  cursor: pointer;
  touch-action: none;
  transition: background 0.1s, transform 0.08s;
  padding: 0;
}
.p1 .dbtn { border-color: rgba(255, 106, 61, 0.35); }
.p2 .dbtn { border-color: rgba(91, 231, 255, 0.35); }
.dbtn.active, .dbtn:active { background: rgba(255, 255, 255, 0.18); transform: scale(0.94); }
.dbtn.up { grid-area: 1 / 2; }
.dbtn.left { grid-area: 2 / 1; }
.dbtn.down { grid-area: 3 / 2; }
.dbtn.right { grid-area: 2 / 3; }

.atk-grid {
  display: grid;
  grid-template-columns: repeat(2, var(--ts));
  grid-template-rows: repeat(2, var(--ts));
  gap: clamp(4px, 0.8vmin, 8px);
  touch-action: none;
}
.abtn {
  appearance: none;
  border-radius: 50%;
  border: 1px solid rgba(255, 255, 255, 0.22);
  background: radial-gradient(circle at 35% 30%, rgba(255, 255, 255, 0.18), rgba(20, 12, 30, 0.72));
  color: #fff4e8;
  font-size: clamp(8px, 1.5vmin, 11px);
  font-weight: 700;
  display: grid;
  place-items: center;
  cursor: pointer;
  touch-action: none;
  padding: 0;
  transition: transform 0.08s, background 0.1s, box-shadow 0.15s;
  text-shadow: 0 1px 2px rgba(0, 0, 0, 0.6);
}
.p1 .abtn { border-color: rgba(255, 140, 90, 0.45); }
.p2 .abtn { border-color: rgba(120, 235, 255, 0.45); }
.abtn.a1 { transform: translateY(calc(var(--ts) * 0.5)); }
.abtn.a2 { transform: translateY(calc(var(--ts) * 0.5)); }
.abtn.a3 { transform: translateY(calc(var(--ts) * -0.5)); }
.abtn.a4 { transform: translateY(calc(var(--ts) * -0.5)); }
.p1 .abtn.a3 { box-shadow: inset 0 0 14px rgba(255, 120, 60, 0.35); }
.p1 .abtn.a4 { border-color: rgba(255, 205, 120, 0.6); box-shadow: inset 0 0 16px rgba(255, 190, 80, 0.35); }
.p2 .abtn.a3 { box-shadow: inset 0 0 14px rgba(70, 200, 255, 0.3); }
.p2 .abtn.a4 { border-color: rgba(190, 245, 255, 0.65); box-shadow: inset 0 0 16px rgba(120, 225, 255, 0.35); }
.abtn.active, .abtn:active { background: radial-gradient(circle at 50% 50%, rgba(255, 255, 255, 0.35), rgba(40, 20, 50, 0.8)); }
.abtn.active { filter: brightness(1.35); }
.abtn.a1 { --press: 0.94; }
.abtn:active { transform: translateY(0) scale(0.92) !important; }

.touch-pause {
  position: absolute;
  top: calc(8px + env(safe-area-inset-top));
  left: 50%;
  transform: translateX(-50%);
  width: 34px;
  height: 34px;
  border-radius: 50%;
  border: 1px solid rgba(255, 255, 255, 0.2);
  background: rgba(10, 6, 18, 0.5);
  color: rgba(255, 240, 230, 0.7);
  font-size: 11px;
  pointer-events: auto;
  display: grid;
  place-items: center;
  cursor: pointer;
  z-index: 5;
}

#touch-controls.cpu-mode .touch-side.p2 .dpad { visibility: hidden; pointer-events: none; }
#touch-controls.cpu-mode .touch-side.p2 .atk-grid { display: none; }

.rotate-hint {
  position: absolute;
  inset: 0;
  display: none;
  align-items: center;
  justify-content: center;
  background: rgba(5, 3, 10, 0.8);
  color: #efe2f0;
  font-size: 14px;
  pointer-events: auto;
  z-index: 20;
  text-align: center;
  padding: 30px;
}
.rotate-hint[hidden] { display: none !important; }
.rotate-hint span { display: inline-block; font-size: 26px; margin-inline-end: 8px; }

/* =========================================================
   Responsive adjustments
   ========================================================= */
@media (max-width: 760px) {
  .menu-panel { border-radius: 16px; }
  .versus { grid-template-columns: 1fr; }
  .vs-mark { display: none; }
  .fighter-card { padding: 8px 12px; }
  .fighter-card.p2 { flex-direction: row-reverse; }
  .fighter-meta .desc { display: none; }
  .versus { gap: 6px; margin: 10px 0; }
  .menu-head h1 { font-size: clamp(34px, 9vmin, 54px); }
  .tagline { display: none; }
  .controls-panel { grid-template-columns: 1fr; max-height: 34vh; overflow: auto; }
  .menu-foot { display: none; }
  .sub-row { width: 100%; }
  .sub-row .ghost-btn { flex: 1; }
  .mode-row { width: 100%; }
  .mode { flex: 1; }
}

@media (max-height: 620px) {
  .menu-panel { padding-top: 12px; padding-bottom: 10px; }
  .menu-head h1 { font-size: clamp(30px, 6.4vmin, 56px); }
  .latin-title { display: none; }
  .tagline { margin-top: 4px; font-size: 10px; }
  .versus { margin: 8px 0; }
  .fighter-card { padding-top: 6px; padding-bottom: 6px; }
  .crest { width: clamp(38px, 7vmin, 56px); }
  .fighter-meta .desc { display: none; }
  .menu-actions { gap: 6px; }
  .cta { padding-top: 7px; padding-bottom: 7px; }
  .menu-foot { display: none; }
  .controls-panel { max-height: 30vh; overflow: auto; }
}

@media (orientation: portrait) and (max-width: 900px) {
  .rotate-hint:not([hidden]) { display: flex; }
  .touch-controls { --ts: clamp(34px, 6.4vmin, 46px); }
}

body.touch-device .ghost-btn,
body.touch-device .mode { -webkit-tap-highlight-color: transparent; }

export const clamp = (v, a, b) => (v < a ? a : v > b ? b : v);
export const lerp = (a, b, t) => a + (b - a) * t;
export const rand = (a = 0, b = 1) => a + Math.random() * (b - a);
export const pick = (arr) => arr[(Math.random() * arr.length) | 0];
export const TAU = Math.PI * 2;

export const easeOutCubic = (t) => 1 - Math.pow(1 - t, 3);
export const easeInCubic = (t) => t * t * t;
export const easeInOutQuad = (t) => (t < 0.5 ? 2 * t * t : 1 - Math.pow(-2 * t + 2, 2) / 2);
export const easeOutBack = (t) => {
  const c1 = 1.70158, c3 = c1 + 1;
  return 1 + c3 * Math.pow(t - 1, 3) + c1 * Math.pow(t - 1, 2);
};

export const toFa = (n) =>
  String(n).replace(/\d/g, (d) => "۰۱۲۳۴۵۶۷۸۹"[+d]);

export function roundRect(ctx, x, y, w, h, r) {
  const rr = Math.min(r, Math.abs(w) / 2, Math.abs(h) / 2);
  ctx.beginPath();
  ctx.moveTo(x + rr, y);
  ctx.arcTo(x + w, y, x + w, y + h, rr);
  ctx.arcTo(x + w, y + h, x, y + h, rr);
  ctx.arcTo(x, y + h, x, y, rr);
  ctx.arcTo(x, y, x + w, y, rr);
  ctx.closePath();
}

export function polygon(ctx, points, close = true) {
  ctx.beginPath();
  points.forEach(([x, y], i) => (i ? ctx.lineTo(x, y) : ctx.moveTo(x, y)));
  if (close) ctx.closePath();
}

/** Rotate point p around origin o by angle (radians). */
export function rotateAround(px, py, ox, oy, angle) {
  const c = Math.cos(angle), s = Math.sin(angle);
  const dx = px - ox, dy = py - oy;
  return [ox + dx * c - dy * s, oy + dx * s + dy * c];
}

/** Filled ellipse helper. */
export function ellipse(ctx, x, y, rx, ry, fill, rot = 0) {
  ctx.beginPath();
  ctx.ellipse(x, y, Math.max(0.1, rx), Math.max(0.1, ry), rot, 0, TAU);
  if (fill) {
    ctx.fillStyle = fill;
    ctx.fill();
  }
}

/** Capsule stroke between two points. */
export function capsule(ctx, x1, y1, x2, y2, width, color) {
  ctx.beginPath();
  ctx.moveTo(x1, y1);
  ctx.lineTo(x2, y2);
  ctx.lineWidth = width;
  ctx.lineCap = "round";
  ctx.strokeStyle = color;
  ctx.stroke();
}

export function capsuleOutline(ctx, x1, y1, x2, y2, width, outline, inner) {
  if (outline) capsule(ctx, x1, y1, x2, y2, width + 5, outline);
  capsule(ctx, x1, y1, x2, y2, width, inner);
}

/** Rect vs rect overlap. Rects are {x,y,w,h}. */
export function overlap(a, b) {
  return a.x < b.x + b.w && a.x + a.w > b.x && a.y < b.y + b.h && a.y + a.h > b.y;
}

export function lerpRect(a, b) {
  // unused placeholder to keep util surface tidy
  return a;
}

/** Small deterministic pseudo random */
export function hash(n) {
  const x = Math.sin(n * 127.1 + 311.7) * 43758.5453;
  return x - Math.floor(x);
}

/**
 * Tiny procedural sound engine — no audio assets required.
 * Everything is synthesized through Web Audio on demand.
 */
export class Sfx {
  constructor() {
    this.ctx = null;
    this.master = null;
    this.noiseBuf = null;
    this.muted = false;
    this.volume = 0.42;
  }

  init() {
    if (this.ctx) return;
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return;
    this.ctx = new AC();
    this.master = this.ctx.createGain();
    this.master.gain.value = this.muted ? 0 : this.volume;
    this.master.connect(this.ctx.destination);

    const len = Math.floor(this.ctx.sampleRate * 0.7);
    const buf = this.ctx.createBuffer(1, len, this.ctx.sampleRate);
    const data = buf.getChannelData(0);
    for (let i = 0; i < len; i++) data[i] = Math.random() * 2 - 1;
    this.noiseBuf = buf;
  }

  resume() {
    this.init();
    if (this.ctx && this.ctx.state === "suspended") this.ctx.resume();
  }

  setMuted(m) {
    this.muted = m;
    if (this.master && this.ctx) {
      this.master.gain.setTargetAtTime(m ? 0 : this.volume, this.ctx.currentTime, 0.02);
    }
  }

  get t() { return this.ctx ? this.ctx.currentTime : 0; }

  tone({ freq = 220, freq2 = null, type = "sine", dur = 0.15, vol = 0.2, delay = 0, attack = 0.004 }) {
    if (!this.ctx || this.muted) return;
    const t0 = this.t + delay;
    const osc = this.ctx.createOscillator();
    const g = this.ctx.createGain();
    osc.type = type;
    osc.frequency.setValueAtTime(Math.max(20, freq), t0);
    if (freq2) osc.frequency.exponentialRampToValueAtTime(Math.max(20, freq2), t0 + dur);
    g.gain.setValueAtTime(0.0001, t0);
    g.gain.exponentialRampToValueAtTime(Math.max(0.0002, vol), t0 + attack);
    g.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
    osc.connect(g).connect(this.master);
    osc.start(t0);
    osc.stop(t0 + dur + 0.02);
  }

  noise({ dur = 0.15, vol = 0.2, freq = 1200, q = 0.9, type = "bandpass", freq2 = null, delay = 0 }) {
    if (!this.ctx || this.muted) return;
    const t0 = this.t + delay;
    const src = this.ctx.createBufferSource();
    src.buffer = this.noiseBuf;
    const filt = this.ctx.createBiquadFilter();
    filt.type = type;
    filt.frequency.setValueAtTime(freq, t0);
    filt.Q.value = q;
    if (freq2) filt.frequency.exponentialRampToValueAtTime(Math.max(40, freq2), t0 + dur);
    const g = this.ctx.createGain();
    g.gain.setValueAtTime(0.0001, t0);
    g.gain.exponentialRampToValueAtTime(Math.max(0.0002, vol), t0 + 0.006);
    g.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
    src.connect(filt).connect(g).connect(this.master);
    src.start(t0);
    src.stop(t0 + dur + 0.02);
  }

  hitLight() {
    this.noise({ dur: 0.1, vol: 0.32, freq: 1900, q: 0.7 });
    this.tone({ freq: 180, freq2: 70, type: "triangle", dur: 0.11, vol: 0.28 });
  }

  hitHeavy() {
    this.noise({ dur: 0.2, vol: 0.4, freq: 900, q: 0.6, type: "lowpass" });
    this.tone({ freq: 120, freq2: 45, type: "sine", dur: 0.28, vol: 0.5 });
    this.tone({ freq: 260, freq2: 90, type: "square", dur: 0.1, vol: 0.12 });
  }

  block() {
    this.noise({ dur: 0.08, vol: 0.22, freq: 3200, q: 2.2 });
    this.tone({ freq: 620, freq2: 420, type: "square", dur: 0.07, vol: 0.08 });
  }

  whiff() {
    this.noise({ dur: 0.14, vol: 0.13, freq: 700, freq2: 2300, q: 0.8 });
  }

  jump() {
    this.tone({ freq: 260, freq2: 430, type: "triangle", dur: 0.14, vol: 0.09 });
  }

  land() {
    this.noise({ dur: 0.08, vol: 0.12, freq: 500, q: 0.7, type: "lowpass" });
  }

  fireball() {
    this.tone({ freq: 220, freq2: 880, type: "sawtooth", dur: 0.34, vol: 0.14 });
    this.noise({ dur: 0.3, vol: 0.16, freq: 500, freq2: 2600, q: 0.9 });
  }

  superMove() {
    this.tone({ freq: 90, freq2: 40, type: "sine", dur: 0.9, vol: 0.45 });
    this.tone({ freq: 440, freq2: 110, type: "sawtooth", dur: 0.7, vol: 0.13 });
    this.noise({ dur: 0.9, vol: 0.3, freq: 2000, freq2: 200, q: 0.6 });
    this.tone({ freq: 880, freq2: 1320, type: "triangle", dur: 0.5, vol: 0.1, delay: 0.1 });
  }

  ko() {
    this.tone({ freq: 70, freq2: 28, type: "sine", dur: 1.1, vol: 0.55 });
    this.noise({ dur: 0.8, vol: 0.35, freq: 1200, freq2: 120, type: "lowpass" });
    this.tone({ freq: 220, freq2: 55, type: "sawtooth", dur: 0.8, vol: 0.12 });
  }

  bell() {
    this.tone({ freq: 880, freq2: 878, type: "triangle", dur: 0.9, vol: 0.14 });
    this.tone({ freq: 1320, freq2: 1318, type: "sine", dur: 0.7, vol: 0.08, delay: 0.02 });
    this.tone({ freq: 1760, freq2: 1758, type: "sine", dur: 0.5, vol: 0.04, delay: 0.03 });
  }

  ui() {
    this.tone({ freq: 520, freq2: 660, type: "sine", dur: 0.07, vol: 0.07 });
  }

  select() {
    this.tone({ freq: 440, type: "triangle", dur: 0.1, vol: 0.1 });
    this.tone({ freq: 660, type: "triangle", dur: 0.14, vol: 0.08, delay: 0.06 });
  }

  fight() {
    this.bell();
    this.tone({ freq: 160, freq2: 320, type: "sawtooth", dur: 0.3, vol: 0.1 });
    this.noise({ dur: 0.25, vol: 0.2, freq: 800, freq2: 2400 });
  }

  timeUp() {
    this.tone({ freq: 440, freq2: 440, type: "square", dur: 0.16, vol: 0.1 });
    this.tone({ freq: 330, freq2: 330, type: "square", dur: 0.3, vol: 0.1, delay: 0.2 });
  }
}

/** Keyboard + multi-touch input mapped to physical key codes. */
export class Input {
  constructor() {
    this.held = new Set();
    this.pressed = new Set();
    this.released = new Set();
    this.enabled = true;
    this.touchActive = false;

    this._onKeyDown = (e) => {
      const code = e.code;
      if (PREVENT.has(code)) e.preventDefault();
      if (!this.enabled) return;
      if (code === "Space" || code === "Enter") e.preventDefault();
      if (e.repeat) return;
      if (!this.held.has(code)) this.pressed.add(code);
      this.held.add(code);
    };
    this._onKeyUp = (e) => {
      const code = e.code;
      this.held.delete(code);
      this.released.add(code);
      if (PREVENT.has(code)) e.preventDefault();
    };
    this._onBlur = () => {
      this.held.clear();
      this.pressed.clear();
    };

    window.addEventListener("keydown", this._onKeyDown, { passive: false });
    window.addEventListener("keyup", this._onKeyUp, { passive: false });
    window.addEventListener("blur", this._onBlur);
  }

  down(code) {
    if (!this.held.has(code)) this.pressed.add(code);
    this.held.add(code);
  }

  up(code) {
    this.held.delete(code);
    this.released.add(code);
  }

  isHeld(code) {
    return this.held.has(code);
  }

  wasPressed(code) {
    return this.pressed.has(code);
  }

  endFrame() {
    this.pressed.clear();
    this.released.clear();
  }

  clear() {
    this.held.clear();
    this.pressed.clear();
  }

  /** Bind pointer events on elements carrying data-code attributes. */
  bindTouch(root) {
    const activePointers = new Map();
    const clearBtn = (btn) => btn.classList.remove("active");

    root.querySelectorAll("[data-code]").forEach((btn) => {
      btn.addEventListener("pointerdown", (e) => {
        e.preventDefault();
        e.stopPropagation();
        btn.setPointerCapture?.(e.pointerId);
        const code = btn.dataset.code;
        activePointers.set(e.pointerId, { code, btn });
        btn.classList.add("active");
        this.touchActive = true;
        this.down(code);
      });
      const release = (e) => {
        const rec = activePointers.get(e.pointerId);
        if (!rec) return;
        activePointers.delete(e.pointerId);
        this.up(rec.code);
        clearBtn(rec.btn);
      };
      btn.addEventListener("pointerup", release);
      btn.addEventListener("pointercancel", release);
      btn.addEventListener("lostpointercapture", release);
      btn.addEventListener("contextmenu", (e) => e.preventDefault());
    });
  }
}

const PREVENT = new Set([
  "ArrowUp", "ArrowDown", "ArrowLeft", "ArrowRight",
  "Space", "Enter", "KeyW", "KeyA", "KeyS", "KeyD",
  "KeyJ", "KeyK", "KeyL", "KeyI", "KeyP",
  "Digit1", "Digit2", "Digit3", "Digit4",
  "Numpad1", "Numpad2", "Numpad3", "Numpad4",
]);

